 juce::TextButton clipTab{"CLIP"},arpTab{"ARP"},power{"ENABLE"},stop{"STOP ALL"},record{"RECORD"},midiIn{"IMPORT MIDI"},midiOut{"EXPORT MIDI"},bankSave{"SAVE BANK"},bankLoad{"LOAD BANK"},rename{"RENAME"},clear{"CLEAR"},demo{"DEMO"};std::array<juce::TextButton,12> slots;juce::ComboBox lane,grid;std::unique_ptr<juce::FileChooser> chooser;
 void timerCallback()override{p.drainSequenceRecording();int selected=juce::jlimit(0,11,(int)p.value(arp?"seqArpSlot":"seqClipSlot"));if(slot!=selected)rebuild(selected);auto bank=p.sequences();for(int i=0;i<12;++i){auto& data=arp?bank->arps[i]:bank->clips[i];slots[i].setButtonText(juce::String(i+1)+"  "+data.name);slots[i].setToggleState(i==slot,juce::dontSendNotification);slots[i].setColour(juce::TextButton::textColourOffId,!arp&&(p.clipPlayingMask.load()&(1<<i))?nd::colour(juce::Colour(0xff6fdb8c)):juce::Colour(0xffa9bdca));}power.setToggleState(arp?p.sequenceArpEnabled():p.value("seqClipEnabled")>.5f,juce::dontSendNotification);power.setButtonText(arp?(p.sequenceArpEnabled()?"ARP ON":"ARP OFF"):(p.value("seqClipEnabled")>.5f?"CLIP ON":"CLIP OFF"));record.setToggleState(p.value("seqRecord")>.5f,juce::dontSendNotification);roll.repaint();}
