 void toggle(juce::String id,juce::String title,int x,int y,int width=100){auto* c=dynamic_cast<juce::TextButton*>(controls.add(new juce::TextButton(title)));addAndMakeVisible(c);c->setClickingTogglesState(true);c->setBounds(x,y,width,23);buttonLinks.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(p.state,id,*c));}
 void rebuild(int selected){comboLinks.clear();buttonLinks.clear();controls.clear();slot=selected;advanced.setVisible(arp);clipAdvanced.setVisible(!arp);roll.setVisible(false);lane.setVisible(false);grid.setVisible(false);for(auto& button:slots)button.setVisible(false);if(!arp){clipAdvanced.setSlot(slot);record.setEnabled(true);midiIn.setEnabled(true);midiOut.setEnabled(true);return;}if(arp){advanced.setSlot(slot);record.setEnabled(false);midiIn.setEnabled(false);midiOut.setEnabled(false);return;}roll.setSlot(arp,slot);if(arp){auto a=seqId(true,slot,"");choice(a+"shape",12,96,204);choice(a+"rate",12,137,100);toggle(a+"free","Hz MODE",118,137,98);knob(a+"hz","FREE RATE Hz",12,171);toggle(a+"triplet","TRIPLET",118,174,98);toggle(a+"dotted","DOTTED",118,203,98);knob(a+"range","RANGE",12,234);knob(a+"shift","SHIFT st",118,234);knob(a+"gate","GATE",12,280);knob(a+"chance","CHANCE",118,280);toggle(a+"latch","LATCH",12,329);toggle(a+"thru","THRU",118,329);knob(a+"offset","OFFSET",12,365);knob(a+"repeats","REPEATS / 0 = inf",118,365);choice(a+"retrigger",12,416,204);knob(a+"decay","VELOCITY DECAY",12,453);knob(a+"target","TARGET",118,453);knob(a+"length","PATTERN BEATS",12,502,204);}else{auto c=seqId(false,slot,"");knob(c+"length","LENGTH / BEATS",12,98,204);choice(c+"mode",12,153,204);choice(c+"rate",12,195,204);knob(c+"transpose","TRANSPOSE st",12,234,204);choice("seqQuant",12,294,204);toggle("seqClipPoly","POLY CLIPS",12,336,204);toggle("seqHost","HOST TRANSPORT",12,370,204);knob("seqTriggerOctave","MIDI TRIGGER OCT / -1 OFF",12,410,204);choice(c+"span",12,466,204);}knob("seqTempo","TEMPO / NO HOST",556,79,145);choice("seqKey",12,565,98,{"Key Off","C","C#","D","D#","E","F","F#","G","G#","A","A#","B"});choice("seqScale",118,565,98);choice("seqMidiOut",12,605,204);record.setEnabled(!arp);midiIn.setEnabled(!arp);midiOut.setEnabled(!arp);}
 void midiFile(bool writing){chooser=std::make_unique<juce::FileChooser>(writing?"Export MIDI clip":"Import MIDI clip",juce::File::getSpecialLocation(juce::File::userDocumentsDirectory),"*.mid;*.midi");auto safe=juce::Component::SafePointer<SequencerPage>(this);chooser->launchAsync((writing?juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::warnAboutOverwriting:juce::FileBrowserComponent::openMode)|juce::FileBrowserComponent::canSelectFiles,[safe,writing](const juce::FileChooser& fc){if(!safe||fc.getResult()==juce::File())return;juce::String error;bool ok=writing?safe->p.exportSequenceMidi(safe->slot,fc.getResult().withFileExtension("mid"),error):safe->p.importSequenceMidi(safe->slot,fc.getResult(),error);if(!ok)juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,"MIDI clip",error);safe->roll.setSlot(false,safe->slot);});}
