 explicit SequencerPage(SynthProcessor& processor):p(processor),roll(p){using namespace juce;setComponentID("sequencer-page");setLookAndFeel(&theme);theme.attach(*this);addChildComponent(clipAdvanced);clipAdvanced.setBounds(0,34,1208,633);addChildComponent(advanced);advanced.setBounds(0,34,1208,633);addAndMakeVisible(roll);roll.setBounds(230,120,970,545);TextButton* buttons[]={&clipTab,&arpTab,&power,&stop,&record,&midiIn,&midiOut,&bankSave,&bankLoad,&rename,&clear,&demo};int xs[]={0,88,182,280,372,466,577,688,804,920,1016,1106},widths[]={82,82,86,86,86,105,105,110,110,90,85,94};for(int i=0;i<12;++i){addAndMakeVisible(*buttons[i]);buttons[i]->setBounds(xs[i],0,widths[i],30);}for(auto* tab:{&clipTab,&arpTab}){OscModernTheme::styleTab(*tab);tab->getProperties().set("roundedModTab",true);}clipTab.onClick=[this]{setMode(false);};arpTab.onClick=[this]{setMode(true);};power.onClick=[this]{if(arp)p.setSequenceArpEnabled(!p.sequenceArpEnabled());else p.set("seqClipEnabled",1-p.value("seqClipEnabled"));};stop.onClick=[this]{p.clipRequest.store(24);p.set("seqRecord",0);};record.onClick=[this]{if(!arp){clipAdvanced.toggleRecording();return;}p.set("seqRecord",1-p.value("seqRecord"));if(p.value("seqRecord")>.5f){p.set("seqClipEnabled",1);if(!(p.clipPlayingMask.load()&(1<<slot)))p.clipRequest.store(slot);}};midiIn.onClick=[this]{midiFile(false);};midiOut.onClick=[this]{midiFile(true);};midiOut.setTooltip("Export notes and MIDI controllers. Macro automation stays in presets / .ncseq banks.");bankSave.onClick=[this]{if(arp)advanced.file(true,true);else clipAdvanced.file(true,true);};bankLoad.onClick=[this]{if(arp)advanced.file(false,true);else clipAdvanced.file(false,true);};rename.onClick=[this]{auto bank=p.sequences();auto* dialog=new AlertWindow("Rename sequence","Name of the selected slot",MessageBoxIconType::NoIcon,this);dialog->addTextEditor("name",arp?bank->arps[slot].name:bank->clips[slot].name);dialog->addButton("SAVE",1);dialog->addButton("CANCEL",0);auto safe=Component::SafePointer<SequencerPage>(this);bool mode=arp;int index=slot;dialog->enterModalState(true,ModalCallbackFunction::create([safe,dialog,mode,index](int result){if(safe&&result==1){auto next=std::make_shared<SequencerBank>(*safe->p.sequences());(mode?next->arps[index]:next->clips[index]).name=dialog->getTextEditorContents("name").substring(0,128);safe->p.setSequences(next);}}),true);};clear.onClick=[this]{auto bank=std::make_shared<SequencerBank>(*p.sequences());auto& target=arp?bank->arps[slot]:bank->clips[slot];target.notes.clear();target.lanes.clear();p.setSequences(bank);};demo.onClick=[this]{auto bank=std::make_shared<SequencerBank>(*p.sequences());auto& target=arp?bank->arps[slot]:bank->clips[slot];target.notes.clear();for(int i=0;i<8;++i)target.notes.push_back({i*.5,.4,arp?i%4:60+(i%4==0?0:i%4==1?3:i%4==2?7:10),1,.8f,1});p.setSequences(bank);p.set(seqId(arp,slot,"length"),4);if(arp)p.set(seqId(true,slot,"shape"),10);};for(int i=0;i<12;++i){addAndMakeVisible(slots[i]);slots[i].setBounds(i*100,41,98,34);slots[i].setComponentID("sequence-slot:"+String(i));OscModernTheme::styleTab(slots[i]);slots[i].getProperties().set("roundedModTab",true);slots[i].setTooltip("Click: select and launch/stop. Shift-click: select without playback.");slots[i].onClick=[this,i]{p.set(arp?"seqArpSlot":"seqClipSlot",(float)i);if(!arp&&!juce::ModifierKeys::getCurrentModifiers().isShiftDown()){p.set("seqClipEnabled",1);p.clipRequest.store(i);}rebuild(i);};}addAndMakeVisible(lane);lane.addItemList({"Velocity","Chance","CC1 / Mod wheel","CC74 / Timbre","Pitch bend","Pressure","Macro 1","Macro 2","Macro 3","Macro 4","Macro 5","Macro 6","Macro 7","Macro 8"},1);lane.setSelectedId(1);lane.setBounds(234,92,177,24);lane.onChange=[this]{int n=lane.getSelectedItemIndex(),targets[]={-1,-2,1,74,128,129,130,131,132,133,134,135,136,137};roll.setLane(targets[jlimit(0,13,n)]);};addAndMakeVisible(grid);grid.addItemList({"Grid 1/8","Grid 1/16","Grid 1/32"},1);grid.setSelectedId(2);grid.setBounds(420,92,128,24);grid.onChange=[this]{roll.setGrid(std::pow(2.,-grid.getSelectedItemIndex()-1));};setMode(false);startTimerHz(25);}
 ~SequencerPage()override{stopTimer();comboLinks.clear();buttonLinks.clear();controls.clear();setLookAndFeel(nullptr);}
 void setMode(bool isArp){arp=isArp;clipTab.setToggleState(!arp,juce::dontSendNotification);arpTab.setToggleState(arp,juce::dontSendNotification);rebuild(juce::jlimit(0,11,(int)p.value(arp?"seqArpSlot":"seqClipSlot")));timerCallback();}
 void paint(juce::Graphics& g)override{nd::Scope suitScope("controls");g.fillAll(UiStyle::canvas());return;UiStyle::card(g,juce::Rectangle<float>(0,87,224,580));UiStyle::header(g,juce::Rectangle<float>(0,87,224,24),{});g.setColour(nd::colour(nd::colour(juce::Colour(0xff91a7b9))));g.setFont(juce::FontOptions(nd::number("fontSize",9)));g.drawText(arp?"Hold notes / use Clip as input. Pattern: draw degrees in the grid.":"Click a slot to play/stop. Draw notes; drag the right edge for length.",714,92,482,24,juce::Justification::centredLeft);g.drawText("MIDI: Off / Clip only / Clip + Arp",12,638,207,20,juce::Justification::centredLeft);}
